/// A union is a complex type with children in Field
/// By default ids in the type vector refer to the offsets in the children
/// optionally typeIds provides an indirection between the child offset and the type id
/// for each child `typeIds[offset]` is the id used in the type vector
#[derive(PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct Union {
    pub mode: UnionMode,
    pub typeIds: Option<Vec<i32>>,
}

impl Union {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsUnion<'a>> {
        use crate::types::generated::Schema_generated::UnionBuilder as FbsUnionBuilder;

        let typeIds_offset = self.typeIds.as_ref().map(|v| {
            let typeIds_offset = builder.create_vector(&v);
            typeIds_offset
        });

        let mut bldr = FbsUnionBuilder::new(builder);
        bldr.add_mode(FbsUnionMode::from(self.mode));
        if let Some(offset) = typeIds_offset {
            bldr.add_typeIds(offset);
        }
        bldr.finish()
    }
}

impl From<FbsUnion<'_>> for Union {
    fn from(fbs: FbsUnion<'_>) -> Self {
        let mode = UnionMode::from(fbs.mode());
        let typeIds = if let Some(val) = fbs.typeIds() {
            let mut typeIds = Vec::new();
            for elem in val {
                typeIds.push(elem.into());
            }

            Some(typeIds)
        } else {
            None
        };

        Self { mode, typeIds }
    }
}

impl crate::FbsSerde for Union {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsUnion>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

impl Default for Union {
    fn default() -> Self {
        Self {
            mode: UnionMode::Sparse,
            typeIds: None,
        }
    }
}

