        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsDictionaryEncoding>(&opts, bytes)?;
        Ok(Self::from(fbs))
